def open_text(path):
    try:
        return gzip.open(path, "rt")
    except OSError:
        return open(path, "rt")


def quantile(values, q):
    if not values:
        return "NA"
    a = sorted(values)
    pos = (len(a) - 1) * q
    lo = math.floor(pos)
    hi = math.ceil(pos)
    if lo == hi:
        return a[lo]
    return a[lo] + (a[hi] - a[lo]) * (pos - lo)


