seq_path = sys.argv[1]
pwm_path = sys.argv[2]


def read_pwm(path):
    rows = []
    background = {}
    in_matrix = False
    with open(path) as fh:
        for raw in fh:
            line = raw.strip()
            if line.startswith("Background letter frequencies"):
                for base, value in re.findall(r"([ACGT])\s+([0-9.]+)", line):
                    background[base] = float(value)
            if line.startswith("letter-probability matrix"):
                in_matrix = True

